\min_{p,\, \theta} \mathbb{E}_{\tau \sim p(\tau)}[c(\tau)] \quad \\
\text{s.t.} \quad p(u_t \mid x_t) = \pi_{\theta}(u_t \mid x_t)
\end{align}
}
\]

